const META_TAG_NAME="x-mail-obf";const CONFIG_META_TAG_NAME="x-mail-obf-config";const KEY_DERIVATION_CONTEXT="functionfly/mail-obfuscation/v2:";export function readConfig(){const fallback={encrypted:true};if(typeof document==="undefined")return fallback;const meta=document.querySelector(`meta[name="${CONFIG_META_TAG_NAME}"]`);const content=meta?.getAttribute("content");if(!content)return fallback;try{const parsed=JSON.parse(content);return{encrypted:parsed.encrypted!==false}}catch{return fallback}}export function base64UrlToBytes(value){const base64=value.replace(/-/g,"+").replace(/_/g,"/");const padded=base64.padEnd(base64.length+(4-base64.length%4)%4,"=");const binary=atob(padded);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++){bytes[i]=binary.charCodeAt(i)}return bytes}export function hexToBytes(hex){const bytes=new Uint8Array(hex.length/2);for(let i=0;i<hex.length;i+=2){bytes[i/2]=parseInt(hex.substring(i,i+2),16)}return bytes}export function bytesToHex(bytes){let out="";for(const byte of bytes){out+=byte.toString(16).padStart(2,"0")}return out}export function constantTimeEqual(a,b){if(a.length!==b.length)return false;let result=0;for(let i=0;i<a.length;i++){result|=a.charCodeAt(i)^b.charCodeAt(i)}return result===0}function bytesToString(bytes){return(new TextDecoder).decode(bytes)}async function deriveMetaKey(salt){const encoded=(new TextEncoder).encode(KEY_DERIVATION_CONTEXT+salt);const digest=await crypto.subtle.digest("SHA-256",encoded);return new Uint8Array(digest)}async function aesDecrypt(payload,key){const bytes=base64UrlToBytes(payload);if(bytes.length<28){throw new Error("encrypted meta tag is too short to be valid")}const iv=bytes.slice(0,12);const ciphertextWithTag=bytes.slice(12);const cryptoKey=await crypto.subtle.importKey("raw",key,{name:"AES-GCM"},false,["decrypt"]);const plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:iv},cryptoKey,ciphertextWithTag);return bytesToString(new Uint8Array(plain))}async function hmacSha256(data,key){const cryptoKey=await crypto.subtle.importKey("raw",(new TextEncoder).encode(key),{name:"HMAC",hash:"SHA-256"},false,["sign"]);const signature=await crypto.subtle.sign("HMAC",cryptoKey,(new TextEncoder).encode(data));return bytesToHex(new Uint8Array(signature))}export async function getKeyMaterial(content,config){if(!content)return null;const parts=content.split(":");if(parts.length!==4)return null;const[version,payload,checksum,salt]=parts;try{if(version==="v2"){const metaKey=await deriveMetaKey(salt);const key=await aesDecrypt(payload,metaKey);const expected=await hmacSha256(payload,key);if(!constantTimeEqual(expected,checksum)){console.error("[mail-obfuscation] The key material failed its integrity check.");return null}return{key:key,salt:salt}}if(version==="v1"){const expected=await hmacSha256(payload,payload);if(!constantTimeEqual(expected,checksum)){console.error("[mail-obfuscation] The key material failed its integrity check.");return null}return{key:payload,salt:salt}}}catch(error){console.error("[mail-obfuscation] Failed to read the key material:",error);return null}return null}export function decodeValue(value,method,keyHex){try{const dataBytes=base64UrlToBytes(value);const keyBytes=hexToBytes(keyHex);if(keyBytes.length===0)return null;const result=new Uint8Array(dataBytes.length);for(let i=0;i<dataBytes.length;i++){const keyByte=keyBytes[i%keyBytes.length];switch(method){case"1":result[i]=dataBytes[i]^keyByte;break;case"2":result[i]=dataBytes[i]^keyByte^i&255;break;case"3":{const saltMix=keyBytes[(i*7+13)%keyBytes.length];result[i]=dataBytes[i]^keyByte^saltMix;break}default:result[i]=dataBytes[i]^keyByte}}return bytesToString(result)}catch(error){console.error(`[mail-obfuscation] Decryption error in method ${method}:`,error);return null}}export async function deobfuscateContent(){if(typeof document==="undefined")return;const elements=document.querySelectorAll("[data-mobfuscated]");if(!elements.length)return;const meta=document.querySelector(`meta[name="${META_TAG_NAME}"]`);const keyMaterial=await getKeyMaterial(meta?.getAttribute("content")??null,readConfig());if(!keyMaterial){console.warn("[mail-obfuscation] Could not retrieve key material");return}const{key:key}=keyMaterial;elements.forEach(el=>{const encryptedHref=el.getAttribute("data-href");const encryptedContent=el.getAttribute("data-mobfuscated");const method=el.getAttribute("data-method")||"1";if(!encryptedContent)return;const content=decodeValue(encryptedContent,method,key);if(content===null)return;if(encryptedHref){const href=decodeValue(encryptedHref,method,key);if(href){el.setAttribute("href",href)}}const noscript=el.querySelector("noscript");if(noscript)noscript.remove();el.innerHTML=content;el.removeAttribute("data-mobfuscated");el.removeAttribute("data-method");el.removeAttribute("data-href")})}function init(){let decryptionPerformed=false;const initDeobfuscation=()=>{if(decryptionPerformed)return;decryptionPerformed=true;void deobfuscateContent()};if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initDeobfuscation)}else{initDeobfuscation()}document.addEventListener("astro:page-load",()=>{decryptionPerformed=false;initDeobfuscation()})}if(typeof document!=="undefined"){init()}